function validarCorreo(t){if("string"!=typeof t)return!1;const r=t.trim();return/^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/.test(r)&&!r.includes("..")}function soloLetras(t){if("string"!=typeof t)return!1;return/^[A-Za-zÁÉÍÓÚáéíóúÜüÑñ]+( [A-Za-zÁÉÍÓÚáéíóúÜüÑñ]+)*$/.test(t.trim())}function validarLongitud(t,r){if(null==t)return!1;if(!Number.isInteger(r)||r<=0)return!1;const e=String(t).trim();return/^\d+$/.test(e)&&e.length<=r}function _convertirFecha(t){if(t instanceof Date)return isNaN(t.getTime())?null:t;if("string"!=typeof t)return null;const r=t.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!r)return null;const e=Number(r[1]),n=Number(r[2]),i=Number(r[3]),u=new Date(e,n-1,i);return u.getFullYear()!==e||u.getMonth()!==n-1||u.getDate()!==i?null:u}function calcularEdad(t){const r=_convertirFecha(t);if(!r)return-1;const e=new Date;if(r>e)return-1;let n=e.getFullYear()-r.getFullYear();return(e.getMonth()<r.getMonth()||e.getMonth()===r.getMonth()&&e.getDate()<r.getDate())&&n--,n}function esMayorDeEdad(t){return calcularEdad(t)>=18}function validarPassword(t){if("string"!=typeof t)return!1;return/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9\s])\S{8,}$/.test(t)}function validarCURP(t){if("string"!=typeof t)return!1;const r=t.trim().toUpperCase(),e=new RegExp("^[A-Z][AEIOUX][A-Z]{2}(\\d{2})(\\d{2})(\\d{2})[HMX](AS|BC|BS|CC|CL|CM|CS|CH|DF|DG|GT|GR|HG|JC|MC|MN|MS|NT|NL|OC|PL|QT|QR|SP|SL|SR|TC|TS|TL|VZ|YN|ZS|NE)[B-DF-HJ-NP-TV-Z]{3}[0-9A-Z]\\d$"),n=r.match(e);if(!n)return!1;if(!_convertirFecha(`${(/\d/.test(r[16])?1900:2e3)+Number(n[1])}-${n[2]}-${n[3]}`))return!1;let i=0;for(let t=0;t<17;t++)i+="0123456789ABCDEFGHIJKLMNÑOPQRSTUVWXYZ".indexOf(r[t])*(18-t);return(10-i%10)%10===Number(r[17])}function formatearTelefono(t){if(null==t)return null;let r=String(t).replace(/\D/g,"");return 12===r.length&&r.startsWith("52")&&(r=r.slice(2)),10===r.length&&validarLongitud(r,10)?`${r.slice(0,3)} ${r.slice(3,6)} ${r.slice(6)}`:null}function validarCodigoPostal(t){if(null==t)return!1;const r=String(t).trim();return validarLongitud(r,5)&&5===r.length&&!r.startsWith("00")}function validarRFC(t,r){if("string"!=typeof t)return!1;const e=t.trim().toUpperCase(),n=e.match(/^[A-ZÑ&]{4}(\d{2})(\d{2})(\d{2})[A-Z0-9]{3}$/);if(!n)return!1;const i=`-${n[2]}-${n[3]}`;return!(!_convertirFecha(`19${n[1]}${i}`)&&!_convertirFecha(`20${n[1]}${i}`))&&(null==r||""===r||e.slice(0,10)===String(r).trim().toUpperCase().slice(0,10))}